/**
 * 播放/暫停按鈕插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { playIcon, pauseIcon } from '../../renderer/icons';
import styles from './styles.css?inline';

export interface PlayButtonPluginOptions extends ControlPluginOptions {
    /** 按鈕位置：left 或 right */
    position?: 'left' | 'right';
    /** 插入順序（數字越小越前面） */
    order?: number;
}

export const PlayButtonPlugin: MpvPlugin<PlayButtonPluginOptions> = {
    name: 'playButton',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new PlayButtonManager(player, {
            position: options.position ?? 'left',
            order: options.order ?? 0,
        });
    },
};

export class PlayButtonManager extends ControlPlugin<Required<PlayButtonPluginOptions>> {
    readonly name = 'playButton';

    protected createEl(): HTMLElement {
        const btn = document.createElement('button');
        btn.className = 'vp-btn vp-play-btn';
        btn.title = '播放/暫停 (Space)';
        btn.innerHTML = `
            <span class="vp-icon-play">${playIcon}</span>
            <span class="vp-icon-pause">${pauseIcon}</span>
        `;

        // 點擊切換播放
        this.on(btn, 'click', (e) => {
            e.stopPropagation();
            this.player[this.player.paused ? 'play' : 'pause']();
        });

        // 監聽播放狀態變化
        this.onPlayer('play', () => this.updateState());
        this.onPlayer('pause', () => this.updateState());

        return btn;
    }

    private updateState(): void {
        if (!this.el) return;
        const isPlaying = !this.player.paused;
        this.el.classList.toggle('playing', isPlaying);
    }
}
